@customElement('bluepad-panel')
class BluepadPanel extends LitElement {
    @state() accessor devices = [];
    @state() accessor pairingEnabled = false;
    @state() accessor showDeviceLoader = true;
    @state() accessor liveBluepadData = null;
    @state() accessor liveBluepadTimedOut = false;

    bluepadConfig = {};
    running = false;
    pollTimer = null;
    temporaryConfigRequest = null;
    bluepadWebSocket = null;
    bluepadWebSocketReconnectTimer = null;
    bluepadMessageTimeoutTimer = null;
    bluepadMessageTimedOut = false;
    bluepadLastMessageAt = 0;
    bluepadLastDataLogAt = 0;
    lastUnexpectedHciState = null;

    constructor() {
        super();
        this.getPairedDevices = this.getPairedDevices.bind(this);
        this.handleBluepadDataEvent = this.handleBluepadDataEvent.bind(this);
        this.handleBluepadMessageTimeoutEvent = this.handleBluepadMessageTimeoutEvent.bind(this);
    }

    connectedCallback() {
        super.connectedCallback();
        this.addEventListener('bluepad-data', this.handleBluepadDataEvent);
        this.addEventListener('bluepad-message-timeout', this.handleBluepadMessageTimeoutEvent);
    }

    createRenderRoot() {
        this.loadBluepadConfigFromState();
        return this;
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        this.running = false;
        if (this.pollTimer) {
            clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }
        if (this.temporaryConfigRequest) {
            this.temporaryConfigRequest.abort();
            this.temporaryConfigRequest = null;
        }
        this.removeEventListener('bluepad-data', this.handleBluepadDataEvent);
        this.removeEventListener('bluepad-message-timeout', this.handleBluepadMessageTimeoutEvent);
        this.closeBluepadWebSocket();
    }

    updated(_) {
        if (!this.running) {
            this.running = true;
            this.getPairedDevices();
            this.sendTemporaryConfig();
            this.connectBluepadWebSocket();
        }

        this.updateLiveGamepadSvg();
    }

    render() {
        if (!this.isFeatureAvailable()) {
            return html`
                <div class="mui-panel mui--text-title">Bluepad32</div>
                <div class="mui-panel">
                    <p>This firmware does not support Bluepad functionality.</p>
                </div>
            `;
        }

        const warnings = this.validationWarnings();

        return html`
            ${this.renderBluepadPreviewStyles()}
            <div class="mui-panel mui--text-title">Bluepad32</div>
            <div class="mui-panel">
                <p>
                    Configure Bluetooth gamepad pairing, manage paired controllers, and map controller inputs onto
                    the main controls and two auxiliary channels.
                </p>
                ${this.renderPairingControls()}
                ${this.renderLivePreview()}
                ${this.renderConfigEditor(warnings)}
            </div>
        `;
    }

    renderPairingControls() {
        return html`
            <h3>Pairing</h3>
            <div class="mui-panel info-bg">
                Pairing is currently <b>${this.pairingEnabled ? 'enabled' : 'disabled'}</b>.
                Previously paired controllers may reconnect even while pairing is disabled.
            </div>
            <div>
                <button class="mui-btn mui-btn--primary" ?disabled="${this.pairingEnabled}" @click="${(event) => this.setPairing(event, true)}">Enable Pairing</button>
                <button class="mui-btn mui-btn--primary" ?disabled="${!this.pairingEnabled}" @click="${(event) => this.setPairing(event, false)}" style="background-color: #FF0;">Disable Pairing</button>
                <button class="mui-btn mui-btn--danger" ?disabled="${this.devices.length === 0}" @click="${(event) => this.deleteAllDevices(event)}">Forget All Devices</button>
            </div>
            <h4>Paired Devices</h4>
            ${this.showDeviceLoader ? html`<div class="loader"></div>` : ''}
            ${this.devices.length === 0 ? html`
                <p>No paired BR/EDR devices found.</p>
            ` : html`
                <table class="mui-table">
                    <tbody>
                        ${this.devices.map((device) => html`
                            <tr>
                                <td>${this.renderDeviceLabel(device)}</td>
                                <td><button class="mui-btn mui-btn--small mui-btn--danger" @click="${(event) => this.deleteDevice(event, device.address)}">Delete</button></td>
                            </tr>
                        `)}
                    </tbody>
                </table>
            `}
        `;
    }

    renderDeviceLabel(device) {
        if (device.name) {
            return `${device.address} connected as ${device.name}`;
        }
        return device.address;
    }

    renderLivePreview() {
        const device = this.connectedGamepadDevice();
        if (!device) {
            return '';
        }

        const liveData = this.liveBluepadData;
        const warning = this.livePreviewWarning(liveData);
        const channels = Array.isArray(liveData?.channels) ? liveData.channels : this.emptyChannelData();

        return html`
            <section class="bluepad-preview-section">
                <h3>Live Gamepad Inputs</h3>
                <div class="bluepad-preview-panel">
                    ${warning ? html`<div class="bluepad-preview-warning">${warning}</div>` : ''}
                    <div class="bluepad-preview-controller">
                        <div class="bluepad-preview-svg svg-placeholder">
                            <div class="svg-wrapper">
                                ${unsafeHTML(this.controllerSvgMarkup(device.name))}
                            </div>
                        </div>
                    </div>
                    <div class="bluepad-channel-preview">
                        <h4>Channel Data</h4>
                        <table class="mui-table bluepad-channel-table">
                            <tbody>
                                ${channels.map((channel, index) => this.renderChannelRow(channel, index))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </section>
        `;
    }

    renderChannelRow(channel, index) {
        const crsfValue = this.clampCrsf(channel);
        return html`
            <tr>
                <td>CH${index + 1}</td>
                <td>${this.crsfToUs(crsfValue)} us</td>
                <td>
                    <input
                        type="range"
                        min="${CRSF_CHANNEL_VALUE_STD_MIN}"
                        max="${CRSF_CHANNEL_VALUE_STD_MAX}"
                        .value="${String(crsfValue)}"
                        disabled
                    >
                </td>
            </tr>
        `;
    }

    renderBluepadPreviewStyles() {
        return html`
            <style>
                .bluepad-preview-section {
                    margin-top: 24px;
                }

                .bluepad-preview-panel {
                    border: 1px solid #ddd;
                    border-radius: 4px;
                    padding: 12px;
                    background: #fafafa;
                }

                .bluepad-preview-warning {
                    border-left: 3px solid #f0ad4e;
                    background: #fff8e1;
                    color: #5f4b00;
                    font-size: 13px;
                    line-height: 1.35;
                    margin-bottom: 12px;
                    padding: 6px 10px;
                }

                .bluepad-preview-controller {
                    display: flex;
                    justify-content: center;
                    width: 100%;
                }

                .bluepad-preview-svg {
                    height: min(52vw, 360px);
                    min-height: 220px;
                    width: 100%;
                }

                .svg-wrapper {
                    align-items: center;
                    display: flex;
                    justify-content: center;
                    max-height: 100%;
                    max-width: 100%;
                }

                .svg-wrapper svg {
                    height: auto;
                    max-height: 100%;
                    max-width: 100%;
                    object-fit: contain;
                    overflow: visible;
                    width: auto;
                }

                .bluepad-preview-svg svg path,
                .bluepad-preview-svg svg g,
                .bluepad-preview-svg svg rect {
                    transition: filter 0.05s ease, transform 0.05s ease;
                    transform-box: fill-box;
                    transform-origin: center;
                }

                .bluepad-preview-svg .pressed {
                    filter: brightness(0.6) contrast(1.23);
                }

                .bluepad-channel-preview {
                    margin-top: 16px;
                }

                .bluepad-channel-table td:first-child {
                    width: 64px;
                }

                .bluepad-channel-table td:nth-child(2) {
                    width: 96px;
                }

                .bluepad-channel-table input[type="range"] {
                    min-width: 160px;
                    width: 100%;
                }
            </style>
        `;
    }

    renderConfigEditor(warnings) {
        return html`
            <h3>Configuration</h3>
            <form class="mui-form">
                <div class="mui-select">
                    <select @change="${(event) => this.updateMainMode(event.target.value)}">
                        ${MAIN_MODE_OPTIONS.map((option, index) => html`
                            <option value="${index}" ?selected="${index === this.bluepadConfig.main_mode}">${option.label}</option>
                        `)}
                    </select>
                    <label>Main Analog Control Mode</label>
                </div>

                ${this.renderAuxTable()}
                ${this.renderButtonTable()}
                ${this.renderWarnings(warnings)}

                <button class="mui-btn mui-btn--primary" @click="${(event) => this.save(event)}">Save</button>
            </form>
        `;
    }

    renderAuxTable() {
        return html`
            <h4>Auxiliary Channels</h4>
            <table class="mui-table">
                <thead>
                    <tr>
                        <th>Aux</th>
                        <th>Actual Channel</th>
                        <th>Home Pos.</th>
                        <th>Analog Mode</th>
                    </tr>
                </thead>
                <tbody>
                    ${this.bluepadConfig.aux_mode.map((aux, index) => html`
                        <tr>
                            <td>AUX ${index + 1}</td>
                            <td>${this.renderChannelSelect(aux.actual_channel, (value) => this.updateAux(index, 'actual_channel', value))}</td>
                            <td>${this.renderFailsafeInput(aux, index)}</td>
                            <td>${this.renderAnalogSelect(aux.analog_mode, (value) => this.updateAux(index, 'analog_mode', value))}</td>
                        </tr>
                    `)}
                </tbody>
            </table>
        `;
    }

    renderButtonTable() {
        return html`
            <h4>Buttons for Auxiliary</h4>
            <table class="mui-table">
                <thead>
                    <tr>
                        <th>Button</th>
                        <th>Aux</th>
                        <th>Mode</th>
                        <th>Value / Step</th>
                    </tr>
                </thead>
                <tbody>
                    ${this.bluepadConfig.btn_mode.map((button, index) => html`
                        <tr>
                            <td>${BUTTONS[index].label}</td>
                            <td>
                                <div class="mui-select compact">
                                    <select @change="${(event) => this.updateButton(index, 'aux_chan', event.target.value)}">
                                        <option value="0" ?selected="${button.aux_chan === 0}">AUX 1</option>
                                        <option value="1" ?selected="${button.aux_chan === 1}">AUX 2</option>
                                    </select>
                                </div>
                            </td>
                            <td>
                                <div class="mui-select compact">
                                    <select @change="${(event) => this.updateButton(index, 'mode', event.target.value)}">
                                        ${BUTTON_MODE_OPTIONS.map((label, modeIndex) => html`
                                            <option value="${modeIndex}" ?selected="${modeIndex === button.mode}">${label}</option>
                                        `)}
                                    </select>
                                </div>
                            </td>
                            <td>
                                <div class="mui-textfield compact">
                                    <input type="number" min="0" max="2500" .value="${String(button.value)}" @change="${(event) => this.updateButton(index, 'value', event.target.value)}">
                                </div>
                            </td>
                        </tr>
                    `)}
                </tbody>
            </table>
        `;
    }

    renderChannelSelect(value, onChange) {
        return html`
            <div class="mui-select compact">
                <select @change="${(event) => onChange(event.target.value)}">
                    ${CHANNEL_OPTIONS.map((label, index) => html`
                        <option value="${index}" ?selected="${index === value}">${label}</option>
                    `)}
                </select>
            </div>
        `;
    }

    renderAnalogSelect(value, onChange) {
        return html`
            <div class="mui-select compact">
                <select @change="${(event) => onChange(event.target.value)}">
                    ${ANALOG_MODE_OPTIONS.map((option, index) => html`
                        <option value="${index}" ?selected="${index === value}">${option.label}</option>
                    `)}
                </select>
            </div>
        `;
    }

    renderFailsafeInput(aux, index) {
        return html`
            <div class="mui-textfield compact">
                <input type="number" min="${BLUEPAD_HOME_US_MIN}" max="${BLUEPAD_HOME_US_MAX}" .value="${String(aux.failsafe)}" @change="${(event) => this.updateAux(index, 'failsafe', event.target.value)}">
            </div>
        `;
    }

    renderWarnings(warnings) {
        return html`
            <div class="mui-panel ${warnings.length ? 'warning-bg' : 'info-bg'}">
                ${warnings.length ? html`
                    <b>Warnings</b>
                    <ul>
                        ${warnings.map((warning) => html`<li>${warning}</li>`)}
                    </ul>
                ` : 'No mapping conflicts detected.'}
            </div>
        `;
    }

    setPairing(event, enabled) {
        event.preventDefault();
        post('/bluepad/pairing', `enabled=${enabled ? 1 : 0}`, {
            headers: {'Content-Type': 'application/x-www-form-urlencoded'},
            onload: (xhr) => {
                this.applyDeviceResponse(xhr);
                this.pairingEnabled = enabled;
                this.getPairedDevices(true);
            },
            onerror: async (xhr) => {
                await showAlert('error', 'Bluepad32 Pairing', xhr.responseText || 'Pairing request failed');
            },
        });
    }

    async deleteDevice(event, address) {
        event.preventDefault();
        const result = await cuteAlert({
            type: 'question',
            title: 'Delete Paired Device',
            message: `Forget ${address}? The controller will need to pair again.`,
            confirmText: 'Delete',
            cancelText: 'Cancel',
        });
        if (result !== 'confirm') {
            return;
        }

        post(`/bluepad/devices/delete?addr=${encodeURIComponent(address)}`, {}, {
            onload: (xhr) => {
                this.applyDeviceResponse(xhr);
                this.getPairedDevices(true);
            },
            onerror: async (xhr) => {
                await showAlert('error', 'Delete Paired Device', xhr.responseText || 'Delete request failed');
            },
        });
    }

    async deleteAllDevices(event) {
        event.preventDefault();
        const result = await cuteAlert({
            type: 'question',
            title: 'Forget All Devices',
            message: 'Forget every paired controller? Controllers will need to pair again.',
            confirmText: 'Forget All',
            cancelText: 'Cancel',
        });
        if (result !== 'confirm') {
            return;
        }

        post('/bluepad/devices/delete?addr=all', {}, {
            onload: (xhr) => {
                this.applyDeviceResponse(xhr);
                this.getPairedDevices(true);
            },
            onerror: async (xhr) => {
                await showAlert('error', 'Forget All Devices', xhr.responseText || 'Forget request failed');
            },
        });
    }

    getPairedDevices(immediate = false) {
        if (!this.running) {
            return;
        }

        if (this.pollTimer) {
            clearTimeout(this.pollTimer);
            this.pollTimer = null;
        }

        const request = new XMLHttpRequest();
        request.onload = () => {
            if (!this.running) {
                return;
            }
            if (request.status === 200) {
                this.applyDeviceResponse(request);
                this.showDeviceLoader = false;
            }
            this.scheduleDevicePoll();
        };
        request.onerror = () => {
            if (this.running) {
                this.scheduleDevicePoll();
            }
        };
        request.open('GET', '/bluepad/devices.json', true);
        request.send();

        if (immediate) {
            this.showDeviceLoader = true;
        }
    }

    scheduleDevicePoll() {
        if (!this.running) {
            return;
        }
        this.pollTimer = setTimeout(this.getPairedDevices, PAIRED_DEVICE_POLL_MS);
    }

    applyDeviceResponse(xhr) {
        try {
            const data = JSON.parse(xhr.responseText || '{}');
            if (Array.isArray(data.devices)) {
                this.devices = data.devices;
            }
            if (typeof data.pairing === 'boolean') {
                this.pairingEnabled = data.pairing;
            }
            this.handleHciState(data.hci_state);
        } catch (_) {
        }
    }

    handleHciState(rawState) {
        if (rawState === undefined || rawState === null) {
            return;
        }

        const hciState = Number(rawState);
        if (!Number.isInteger(hciState) || hciState < 0) {
            return;
        }

        if (hciState === BLUEPAD_HCI_STATE_INITIALIZING || hciState === BLUEPAD_HCI_STATE_WORKING) {
            this.lastUnexpectedHciState = null;
            return;
        }

        if (this.lastUnexpectedHciState === hciState) {
            return;
        }

        this.lastUnexpectedHciState = hciState;
        const stateName = BLUEPAD_HCI_STATE_NAMES[hciState] ?? `unknown (${hciState})`;
        console.warn(`Bluepad32 HCI state is unexpectedly ${stateName}.`);
    }

    updateMainMode(value) {
        this.bluepadConfig.main_mode = this.toInt(value, 0, MAIN_MODE_OPTIONS.length - 1, 0);
        this.requestUpdate();
        this.sendTemporaryConfig();
    }

    updateAux(index, key, value) {
        const aux = this.bluepadConfig.aux_mode[index];
        if (key === 'actual_channel') {
            aux.actual_channel = this.toInt(value, 0, 16, 0);
        } else if (key === 'analog_mode') {
            aux.analog_mode = this.toInt(value, 0, ANALOG_MODE_OPTIONS.length - 1, 0);
        } else if (key === 'failsafe') {
            aux.failsafe = this.toInt(value, BLUEPAD_HOME_US_MIN, BLUEPAD_HOME_US_MAX, BLUEPAD_HOME_US_DEFAULT);
        }
        this.requestUpdate();
        this.sendTemporaryConfig();
    }

    updateButton(index, key, value) {
        const button = this.bluepadConfig.btn_mode[index];
        if (key === 'aux_chan') {
            button.aux_chan = this.toInt(value, 0, 1, 0);
        } else if (key === 'mode') {
            button.mode = this.toInt(value, 0, BUTTON_MODE_OPTIONS.length - 1, 0);
        } else if (key === 'value') {
            button.value = this.toInt(value, 0, 2500, 0);
        }
        this.requestUpdate();
        this.sendTemporaryConfig();
    }

    sendTemporaryConfig() {
        if (!this.isFeatureAvailable()) {
            return;
        }

        if (this.temporaryConfigRequest) {
            this.temporaryConfigRequest.abort();
            this.temporaryConfigRequest = null;
        }

        let request = null;
        const clearRequest = () => {
            if (this.temporaryConfigRequest === request) {
                this.temporaryConfigRequest = null;
            }
        };

        request = post(TEMPORARY_CONFIG_URL, {
            bluepad: this.sanitizeConfig(this.bluepadConfig),
        }, {
            onload: clearRequest,
            onerror: clearRequest,
            onabort: clearRequest,
            ontimeout: clearRequest,
        });
        this.temporaryConfigRequest = request;
    }

    connectBluepadWebSocket() {
        if (!this.running || !this.isFeatureAvailable()) {
            return;
        }

        if (this.bluepadWebSocket && (
            this.bluepadWebSocket.readyState === WebSocket.CONNECTING ||
            this.bluepadWebSocket.readyState === WebSocket.OPEN
        )) {
            return;
        }

        this.clearBluepadWebSocketReconnect();
        this.armBluepadMessageTimeout();

        const socket = new WebSocket(this.bluepadWebSocketUrl());
        this.bluepadWebSocket = socket;

        socket.onmessage = (event) => {
            if (this.bluepadWebSocket !== socket) {
                return;
            }
            this.handleBluepadWebSocketMessage(event.data);
        };

        socket.onclose = () => {
            if (this.bluepadWebSocket === socket) {
                this.bluepadWebSocket = null;
            }
            this.scheduleBluepadWebSocketReconnect();
        };

        socket.onerror = () => {
            socket.close();
        };
    }

    closeBluepadWebSocket() {
        this.clearBluepadWebSocketReconnect();
        this.clearBluepadMessageTimeout();

        if (!this.bluepadWebSocket) {
            return;
        }

        const socket = this.bluepadWebSocket;
        this.bluepadWebSocket = null;
        socket.onmessage = null;
        socket.onclose = null;
        socket.onerror = null;
        if (socket.readyState === WebSocket.CONNECTING || socket.readyState === WebSocket.OPEN) {
            socket.close();
        }
    }

    scheduleBluepadWebSocketReconnect() {
        if (!this.running || !this.isFeatureAvailable() || this.bluepadWebSocketReconnectTimer) {
            return;
        }

        this.bluepadWebSocketReconnectTimer = setTimeout(() => {
            this.bluepadWebSocketReconnectTimer = null;
            this.connectBluepadWebSocket();
        }, BLUEPAD_WEBSOCKET_RECONNECT_MS);
    }

    clearBluepadWebSocketReconnect() {
        if (this.bluepadWebSocketReconnectTimer) {
            clearTimeout(this.bluepadWebSocketReconnectTimer);
            this.bluepadWebSocketReconnectTimer = null;
        }
    }

    armBluepadMessageTimeout() {
        this.clearBluepadMessageTimeout();

        if (!this.running || !this.isFeatureAvailable()) {
            return;
        }

        this.bluepadMessageTimeoutTimer = setTimeout(() => {
            this.bluepadMessageTimeoutTimer = null;
            this.emitBluepadMessageTimeout();
        }, BLUEPAD_MESSAGE_TIMEOUT_MS);
    }

    clearBluepadMessageTimeout() {
        if (this.bluepadMessageTimeoutTimer) {
            clearTimeout(this.bluepadMessageTimeoutTimer);
            this.bluepadMessageTimeoutTimer = null;
        }
    }

    handleBluepadWebSocketMessage(data) {
        const messages = this.parseBluepadWebSocketData(data);
        if (messages.length === 0) {
            return;
        }

        this.bluepadMessageTimedOut = false;
        this.bluepadLastMessageAt = Date.now();
        this.armBluepadMessageTimeout();

        for (const message of messages) {
            this.dispatchEvent(new CustomEvent('bluepad-data', {
                bubbles: true,
                composed: true,
                detail: message,
            }));
        }
    }

    parseBluepadWebSocketData(data) {
        if (typeof data !== 'string') {
            return [];
        }

        const messages = [];
        const pattern = /BP:([^;]*);/g;
        let match = pattern.exec(data);
        while (match) {
            const message = this.parseBluepadMessage(match[1]);
            if (message) {
                messages.push(message);
            }
            match = pattern.exec(data);
        }
        return messages;
    }

    parseBluepadMessage(payload) {
        const values = payload.split(',').map((value) => Number.parseInt(value, 10));
        if (values.length !== BLUEPAD_WEB_VALUE_COUNT || values.some((value) => Number.isNaN(value))) {
            return null;
        }

        const gamepad = {};
        BLUEPAD_GAMEPAD_FIELDS.forEach((field, index) => {
            gamepad[field] = values[index];
        });

        return {
            gamepad,
            channels: values.slice(BLUEPAD_CHANNEL_COUNT, BLUEPAD_CHANNEL_COUNT * 2),
            connected: values[BLUEPAD_WEB_VALUE_COUNT - 1] === 1,
            connectedRaw: values[BLUEPAD_WEB_VALUE_COUNT - 1],
            raw: values,
        };
    }

    emitBluepadMessageTimeout() {
        if (this.bluepadMessageTimedOut) {
            return;
        }

        this.bluepadMessageTimedOut = true;
        this.dispatchEvent(new CustomEvent('bluepad-message-timeout', {
            bubbles: true,
            composed: true,
            detail: {
                timeoutMs: BLUEPAD_MESSAGE_TIMEOUT_MS,
                lastMessageAt: this.bluepadLastMessageAt,
            },
        }));
    }

    handleBluepadDataEvent(event) {
        const now = Date.now();
        if (now - this.bluepadLastDataLogAt > 1000) {
            console.log('Bluepad32 data', event.detail);
            this.bluepadLastDataLogAt = now;
        }
        this.liveBluepadData = event.detail;
        this.liveBluepadTimedOut = false;
    }

    handleBluepadMessageTimeoutEvent(event) {
        console.log('Bluepad32 message timeout', event.detail);
        this.liveBluepadTimedOut = true;
    }

    bluepadWebSocketUrl() {
        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        return `${protocol}//${window.location.host}${BLUEPAD_WEBSOCKET_PATH}`;
    }

    updateLiveGamepadSvg() {
        const svg = this.querySelector('.bluepad-preview-svg svg');
        if (!svg) {
            return;
        }

        this.resetLiveGamepadSvg(svg);

        const data = this.liveBluepadData;
        if (!data?.gamepad) {
            return;
        }

        const gamepad = data.gamepad;
        for (const [field, ids] of BLUEPAD_BUTTON_ELEMENT_MAP) {
            this.setSvgPressed(svg, ids, Boolean(gamepad[field]));
        }

        this.setSvgPressed(svg, ['Button_L'], gamepad.brake > BLUEPAD_TRIGGER_PRESSED);
        this.setSvgPressed(svg, ['Button_R'], gamepad.throttle > BLUEPAD_TRIGGER_PRESSED);

        for (const [mask, id] of BLUEPAD_DPAD_ELEMENT_MAP) {
            this.setSvgPressed(svg, [id], (gamepad.dpad & mask) !== 0);
        }

        this.setSvgStick(svg, 'Analog_Stick', gamepad.axisX, gamepad.axisY);
        this.setSvgStick(svg, 'Analog_C_Stick', gamepad.axisRX, gamepad.axisRY);
    }

    resetLiveGamepadSvg(svg) {
        for (const id of BLUEPAD_PRESSED_ELEMENT_IDS) {
            const element = svg.querySelector(`#${id}`);
            if (element) {
                element.classList.remove('pressed');
                element.style.transform = '';
            }
        }
    }

    setSvgPressed(svg, ids, pressed) {
        for (const id of ids) {
            const element = svg.querySelector(`#${id}`);
            if (!element) {
                continue;
            }
            element.classList.toggle('pressed', pressed);
        }
    }

    setSvgStick(svg, id, xValue, yValue) {
        const element = svg.querySelector(`#${id}`);
        if (!element) {
            return;
        }

        const x = this.axisToTranslatePercent(xValue);
        const y = this.axisToTranslatePercent(yValue);
        element.style.transform = `translate(${x}%, ${y}%)`;
    }

    axisToTranslatePercent(value) {
        const normalized = this.clampNumber(value, BLUEPAD_AXIS_MIN, BLUEPAD_AXIS_MAX) / BLUEPAD_AXIS_MAX;
        const deadZone = 0.03;
        if (normalized > -deadZone && normalized < deadZone) {
            return 0;
        }
        return Math.round(normalized * 500) / 100;
    }

    connectedGamepadDevice() {
        return this.devices.find((device) => typeof device.name === 'string' && device.name.length > 0);
    }

    controllerSvgMarkup(gamepadName) {
        const source = this.isXboxGamepadName(gamepadName) ? BLUEPAD_SVG_XBOX : BLUEPAD_SVG_PS4;
        const cached = BLUEPAD_SVG_MARKUP_CACHE.get(source);
        if (cached) {
            return cached;
        }

        const prefix = 'data:image/svg+xml,';
        const markup = source.startsWith(prefix) ? decodeURIComponent(source.slice(prefix.length)) : source;
        BLUEPAD_SVG_MARKUP_CACHE.set(source, markup);
        return markup;
    }

    isXboxGamepadName(gamepadName) {
        return String(gamepadName || '').toLowerCase().includes('xbox');
    }

    livePreviewWarning(liveData) {
        if (this.liveBluepadTimedOut) {
            return 'No live gamepad data has been received for 5 seconds.';
        }
        if (liveData && liveData.connectedRaw !== 1) {
            return 'The live stream is not reporting an active gamepad.';
        }
        return '';
    }

    emptyChannelData() {
        return new Array(BLUEPAD_CHANNEL_COUNT).fill(CRSF_CHANNEL_VALUE_STD_MIN);
    }

    clampCrsf(value) {
        return this.clampNumber(value, CRSF_CHANNEL_VALUE_STD_MIN, CRSF_CHANNEL_VALUE_STD_MAX);
    }

    crsfToUs(value) {
        const crsfValue = this.clampCrsf(value);
        return Math.round(
            US_CHANNEL_VALUE_STD_MIN +
            ((crsfValue - CRSF_CHANNEL_VALUE_STD_MIN) * (US_CHANNEL_VALUE_STD_MAX - US_CHANNEL_VALUE_STD_MIN)) /
            (CRSF_CHANNEL_VALUE_STD_MAX - CRSF_CHANNEL_VALUE_STD_MIN)
        );
    }

    clampNumber(value, minimum, maximum) {
        const numericValue = Number(value);
        if (Number.isNaN(numericValue)) {
            return minimum;
        }
        if (numericValue < minimum) {
            return minimum;
        }
        if (numericValue > maximum) {
            return maximum;
        }
        return numericValue;
    }

    save(event) {
        event.preventDefault();
        const sanitizedConfig = this.sanitizeConfig(this.bluepadConfig);
        saveConfig({
            bluepad: sanitizedConfig,
        }, () => {
            this.bluepadConfig = sanitizedConfig;
            this.requestUpdate();
        });
    }

    validationWarnings() {
        const warnings = [];
        const occupiedBy = new Map();
        const claim = (mask, source) => {
            for (const [flag, label] of OCCUPANCY_LABELS) {
                if ((mask & flag) === 0) {
                    continue;
                }
                const previousSource = occupiedBy.get(flag);
                if (previousSource) {
                    warnings.push(`${source} also uses ${label}, already used by ${previousSource}.`);
                } else {
                    occupiedBy.set(flag, source);
                }
            }
        };

        claim(MAIN_MODE_OPTIONS[this.bluepadConfig.main_mode]?.occupancy || 0, 'Main mode');

        const channels = new Map();
        this.bluepadConfig.aux_mode.forEach((aux, index) => {
            const label = `AUX ${index + 1}`;
            claim(ANALOG_MODE_OPTIONS[aux.analog_mode]?.occupancy || 0, `${label} analog mode`);

            if (aux.actual_channel > 0) {
                const previousAux = channels.get(aux.actual_channel);
                if (previousAux) {
                    warnings.push(`${label} and ${previousAux} both target CH${aux.actual_channel}.`);
                } else {
                    channels.set(aux.actual_channel, label);
                }
            }

            if ((aux.analog_mode === 1 || aux.analog_mode === 2) && (aux.failsafe < 1400 || aux.failsafe > 1600)) {
                warnings.push(`${label} direct stick mode expects a home position near 1500.`);
            } else if (aux.analog_mode >= 3 && aux.analog_mode <= 8 && aux.failsafe > 1100) {
                warnings.push(`${label} relative/trigger mode usually expects a low home position near 988.`);
            }
        });

        this.bluepadConfig.btn_mode.forEach((button, index) => {
            if (button.mode === 0) {
                return;
            }
            claim(BUTTONS[index].occupancy, `${BUTTONS[index].label} button mode`);
        });

        return warnings;
    }

    checkChanged() {
        if (!this.isFeatureAvailable()) {
            return false;
        }
        return JSON.stringify(this.sanitizeConfig(this.bluepadConfig)) !== JSON.stringify(this.sanitizeConfig(elrsState.config.bluepad));
    }

    loadBluepadConfigFromState() {
        this.bluepadConfig = this.sanitizeConfig(elrsState.config.bluepad);
    }

    sanitizeConfig(inputConfig) {
        const source = inputConfig || {};
        const auxModes = Array.isArray(source.aux_mode) ? source.aux_mode : [];
        const buttonModes = Array.isArray(source.btn_mode) ? source.btn_mode : [];
        return {
            main_mode: this.toInt(source.main_mode, 0, MAIN_MODE_OPTIONS.length - 1, 0),
            aux_mode: [0, 1].map((index) => this.sanitizeAux(auxModes[index] || {})),
            btn_mode: BUTTONS.map((_, index) => this.sanitizeButton(buttonModes[index] || {})),
        };
    }

    sanitizeAux(inputAux) {
        const aux = {
            actual_channel: this.toInt(inputAux.actual_channel, 0, 16, 0),
            failsafe: this.toInt(inputAux.failsafe, BLUEPAD_HOME_US_MIN, BLUEPAD_HOME_US_MAX, BLUEPAD_HOME_US_DEFAULT),
            analog_mode: this.toInt(inputAux.analog_mode, 0, ANALOG_MODE_OPTIONS.length - 1, 0),
        };
        return aux;
    }

    sanitizeButton(inputButton) {
        return {
            aux_chan: this.toInt(inputButton.aux_chan, 0, 1, 0),
            mode: this.toInt(inputButton.mode, 0, BUTTON_MODE_OPTIONS.length - 1, 0),
            value: this.toInt(inputButton.value, 0, 2500, 0),
        };
    }

    isFeatureAvailable() {
        return elrsState.config.bluepad !== undefined;
    }

    toInt(value, minimum, maximum, fallback) {
        const parsed = Number.parseInt(value, 10);
        if (Number.isNaN(parsed)) {
            return fallback;
        }
        if (parsed < minimum) {
            return minimum;
        }
        if (parsed > maximum) {
            return maximum;
        }
        return parsed;
    }
}
